dsl:
name: pool
bar: 1h
strategy_pool:
  members:
    - {id: a, strategy: s_a}
    - {id: c, strategy: s_c}
    - {id: probe, strategy: s_probe}
  allocation:
    method: fixed
    ratios: {a: 0.5, c: 0.5, probe: 0}
    switch:
      - when: {empty: probe}
        move: {from: c, to: [a]}
  fees: {spot_bps: 10, swap_bps: 5}
